        answer: "0.25mm 제품으로 부위별로 떼어가며 가볍게 문지르고, 끝나면 진정 케어를 꼭 해주세요. MTS는 한 부위를 문지른 뒤 피부에서 떼어 다음 부위로 옮겨야 하며, 붙인 채로 끌면 긁힌 상처가 생기니 주의해야 합니다. 너무 세게 욕심내지 말고 여러 번 가볍게 문질러 살짝 홍반이 올라오는 정도가 적당해요. 자극 후엔 시카 성분이 들어간 두꺼운 밤 타입 보습제를 덮어 발라 진정을 시켜주거나 마스크팩을 활용하면 좋습니다. 에센스 성분이 너무 많이 든 제품은 자극 직후 따가울 수 있으니 피하시는 게 좋아요. 위생 관리도 중요해서 일회용을 쓰거나 알코올에 담갔다가 컵에 세워 완전히 말린 뒤 사용해야 염증을 예방할 수 있습니다. 트러블이 생기면 즉시 사용을 중단하고 피부과에서 진료를 받아주세요.",
